function utf8_converter($array)
{
    array_walk_recursive($array, function(&$item, $key){
        if(!mb_detect_encoding($item, 'utf-8', true)){
                $item = utf8_encode($item);
        }
    });
 
    return $array;
}

/**
 * Função de mascara
 * @param $val Valor para passar pela mascara
 * @param $mask Padrão de mascara por # Ex CEP: #####-###
 * @return Valor mascarádo
 */
function mask($val, $mask){
	$maskared = '';
	$k = 0;
	for($i = 0; $i<=strlen($mask)-1; $i++){
		if($mask[$i] == '#'){
			if(isset($val[$k])){
				$maskared .= $val[$k++];
			}
		} else {
			if(isset($mask[$i])){
				$maskared .= $mask[$i];
			}
		}
	}
	return $maskared;
}


