function parserData($date){
    $date = strtotime($date);
    return date("d/m/Y", $date);
}

function parserDataEHora($date){
    $date = strtotime($date);
    return date("d/m/Y H:i", $date);
}

function parserDataHoraSegundo($date){
    $date = strtotime($date);
    return date("d/m/Y H:i:s", $date);
}

function parserNumber($value){
	$value = str_replace('.', '', $value);
	$value = str_replace(',', '.', $value);
	$value = str_replace(' ', '', $value);
	return floatval($value);
}

function parserFloat10($value){
	return (float) number_format($value, 10, '.', '');
}

