function quantidadeDiasUteisNoPeriodo($dtInicio, $dtFim, $feriados = []) {
        
	$tsInicio = strtotime($dtInicio);
	$tsFim = strtotime($dtFim);

	$quantidadeDias = 0;
	while ($tsInicio <= $tsFim) {
		$diaIgualFinalSemana = (date('D', $tsInicio) === 'Sat' || date('D', $tsInicio) === 'Sun');
		$diaIgualFeriado = (count($feriados) && in_array(date('Y-m-d', $tsInicio), $feriados));

		$tsInicio += 86400;

		if ($diaIgualFinalSemana || $diaIgualFeriado) {
			continue;
		}

		$quantidadeDias++;
	}

	return $quantidadeDias;
}

function semanaDiaInicialFinal($data){
	$dia_da_semana_array = array('Domingo', 'Segunda', 'Terca', 'Quarta', 'Quinta', 'Sexta', 'Sabado'); 
	$meses_array = array('', 'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'); 
	$dia_da_semana_inicial = date('w', strtotime($data)); 
	$dia_da_semana_inicial_string = $dia_da_semana_array[$dia_da_semana_inicial];  
	$mes = explode("-", $data)[1];
	$arraySemanas = array();

	$x = (int)$dia_da_semana_inicial;
	$y = 0;

	$semana = 1;
	while(true){

		$indexMes = (int)$mes;
		$arraySemanas[$semana][$y]['day_week'] = $data; 
		$arraySemanas[$semana][$y]['day_name'] = $dia_da_semana_array[$x];
		$arraySemanas[$semana][$y]['month_name'] = $meses_array[$indexMes];

		$data = date('Y-m-d', strtotime("+1 day", strtotime($data)));
		$dataVerifi = explode("-", $data);
		if($dataVerifi[1] != $mes){
			break;
		}

		if($x == 6){
			$x = 0;
			$y = 0;
			$semana++;
		} else {
			$x++;
			$y++;
		}

	}

   return $arraySemanas;
}

function parserValorInteiro($value){
    $value = floatval($value);
    return number_format($value, 0, ",", ".");
}

function parserTamanhoArquivo($bytes, $decimals = 2) {
	$sz = 'BKMGTP';
	$factor = floor((strlen($bytes) - 1) / 3);
	return sprintf("%.{$decimals}f", $bytes / pow(1024, $factor)) . @$sz[$factor];
}

function isMobile() {
	$is_mobile = false;

	//Se tiver em branco, não é mobile
	if ( empty($_SERVER['HTTP_USER_AGENT']) ) {
		$is_mobile = false;

	//Senão, se encontrar alguma das expressões abaixo, será mobile
	} elseif ( strpos($_SERVER['HTTP_USER_AGENT'], 'Mobile') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'Android') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'Silk/') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'Kindle') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'BlackBerry') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'Opera Mini') !== false
		|| strpos($_SERVER['HTTP_USER_AGENT'], 'Opera Mobi') !== false ) {
			$is_mobile = true;

	//Senão encontrar nada, não será mobile
	} else {
		$is_mobile = false;
	}

	return $is_mobile;
}
